const C = {
  text:'#EDEDED', t2:'#A1A1A1', t3:'#8F8F8F', brand:'#FF6B2C', ok:'#34D399', warn:'#FBBF24', err:'#FF5A5F', info:'#52A8FF', s2:'#1A1A1A'
};
const CANDS = [
  { id:'faker', repo:'joke2k/faker', blurb:'Python · test data generation', q:0.4, done:6, outcome:'Pass',
    decision:'Healthy, actively maintained and free to import. Little to resurrect and low willingness to pay.',
    sections:[
      {k:'Opportunity', v:'Widely used to generate realistic fake data for tests and fixtures.'},
      {k:'Proposed product', v:'A hosted fake-data API with saved schemas and seeded datasets.'},
      {k:'Risks', v:'Many free alternatives. Teams already import the library directly.'},
      {k:'Unknowns', v:'Whether anyone would pay to host what they already run locally.'}]},
  { id:'fpocket', repo:'fpocket/fpocket', blurb:'C · protein pocket detection', q:0.8, done:10, outcome:'Invest',
    decision:'Useful scientific capability behind a hard-to-build CLI. A hosted upload flow is a clear product.',
    sections:[
      {k:'Opportunity', v:'Pocket detection is an early step in structure-based work, and running the tool locally means building it from source.'},
      {k:'Proposed product', v:'PocketScan: upload a .pdb file and inspect ranked candidate pockets. Free shows the top pocket; Pro at $9/month shows all.'},
      {k:'Risks', v:'The build may have drifted from current toolchains. Results need scientific validation. Compute cost per structure is unmeasured.'},
      {k:'Unknowns', v:'How many users would pay instead of installing locally. Licensing terms for a hosted service need review.'}]},
  { id:'carbon', repo:'carbon-app/carbon', blurb:'TypeScript · code screenshots', q:1.2, done:8, outcome:'Pass',
    decision:'Already hosted and free. A paid version would compete with the original project.',
    sections:[
      {k:'Opportunity', v:'Popular for turning code snippets into shareable images.'},
      {k:'Proposed product', v:'An image-rendering API for docs, changelogs and social posts.'},
      {k:'Risks', v:'The original is free and online. Low price ceiling.'},
      {k:'Unknowns', v:'Demand for an API beyond the existing web app.'}]}
];
const MS = [
  {id:'res', label:'Resurrection started', detail:'Fork and environment prepared', s:10, e:11.5},
  {id:'build', label:'Build repaired', detail:'Toolchain and build fixes', s:11.5, e:13.5},
  {id:'gen', label:'Product generated', detail:'PocketScan interface and API', s:13.5, e:15.5},
  {id:'deploy', label:'Deployed', detail:'Hosting and runtime', s:15.5, e:17.5},
  {id:'money', label:'Monetization enabled', detail:'Pro plan at $9/month', s:17.5, e:19}
];
const END = { success:19, eval:7, repair:12.8 };
const POCKETS = [
  {id:'P1', druggability:0.82, volume:612.4, score:0.71},
  {id:'P2', druggability:0.64, volume:438.9, score:0.55},
  {id:'P3', druggability:0.41, volume:301.2, score:0.38}
];
const fmt = t => { const m = Math.floor(t/60), s = t - m*60; return String(m).padStart(2,'0') + ':' + s.toFixed(1).padStart(4,'0'); };
const PILL = {
  Queued:{fg:C.t3, bg:'rgba(255,255,255,.07)'},
  Analyzing:{fg:C.brand, bg:'rgba(255,107,44,.12)', pulse:true},
  Pass:{fg:C.t2, bg:'rgba(255,255,255,.06)'},
  Invest:{fg:C.info, bg:'rgba(82,168,255,.12)'},
  Failed:{fg:C.err, bg:'rgba(255,90,95,.12)'}
};
const store = {
  mem:false,
  get(){ try { return sessionStorage.getItem('afterlife-demo-pro') === '1'; } catch(e){ return this.mem; } },
  set(v){ this.mem = v; try { v ? sessionStorage.setItem('afterlife-demo-pro','1') : sessionStorage.removeItem('afterlife-demo-pro'); } catch(e){} }
};
const SAMPLE = 'ATOM      1  N   GLY A   1      11.104   6.134  -6.504  1.00  0.00           N\nATOM      2  CA  GLY A   1      11.639   6.071  -5.147  1.00  0.00           C\nATOM      3  C   GLY A   1      13.140   6.310  -5.123  1.00  0.00           C\nATOM      4  O   GLY A   1      13.750   6.120  -6.170  1.00  0.00           O\nEND\n';

function snapshot(t, sc, started){
  const failAt = sc === 'eval' ? 7 : sc === 'repair' ? 12.8 : Infinity;
  const cands = CANDS.map(c => {
    let status;
    if (!started || t < c.q) status = 'Queued';
    else if (sc === 'eval' && t >= failAt && c.done > failAt) status = 'Failed';
    else if (t < c.done) status = 'Analyzing';
    else status = c.outcome;
    return { ...c, status, decidedAt: (status === 'Pass' || status === 'Invest') ? c.done : null };
  });
  const ms = MS.map(m => {
    let status = 'Pending';
    if (!started || sc === 'eval') status = 'Pending';
    else if (sc === 'repair' && t >= failAt && m.s >= 11.5) status = m.id === 'build' ? 'Failed' : 'Pending';
    else if (t >= m.e) status = 'Complete';
    else if (t >= m.s) status = 'In progress';
    return { ...m, status };
  });
  let run = 'idle';
  if (started) run = t >= failAt ? 'failed' : (sc === 'success' && t >= END.success) ? 'complete' : 'running';
  const invested = started && sc !== 'eval' && t >= 10;
  const ev = [[0,'Run started · 3 candidates queued','info']];
  CANDS.forEach(c => ev.push([c.q, 'Analyzing ' + c.repo, 'info']));
  ev.push([6,'Pass · joke2k/faker','muted'],[8,'Pass · carbon-app/carbon','muted']);
  if (sc === 'eval') ev.push([7,'Evaluation failed · evidence collection timed out','err'],[7,'Run stopped · no investment made','err']);
  else {
    ev.push([10,'Invest · fpocket/fpocket · $10 allocated','brand'],[10,'Resurrection started','info'],[11.5,'Environment ready','ok']);
    if (sc === 'repair') ev.push([12.8,'Build repair failed after 3 attempts','err'],[12.8,'Deployment and monetization not started','err']);
    else ev.push([13.5,'Build repaired','ok'],[15.5,'PocketScan generated','ok'],[17.5,'Deployed','ok'],[19,'Monetization enabled','ok'],[19,'PRODUCT LIVE · PocketScan','brand']);
  }
  const events = started ? ev.filter(e => e[0] <= t).sort((a,b) => b[0]-a[0]) : [];
  return { cands, ms, run, invested, live: run === 'complete', events };
}

class Component extends DCLogic {
  state = {
    view: this.props.startView ?? 'portfolio', scenario:'success', runScenario:'success', started:false, t:0, runN:0, sel:'fpocket',
    pScenario:'success', file:null, fileError:'', drag:false, phase:'idle', slow:false, result:null, errorMsg:'',
    pro: this.props.demo.getPro(), checkout:null, notice:'', ...this.props.demo.loadRun()
  };
  componentDidUpdate(){ this.props.demo.saveRun(this.state); }
  componentDidMount(){
    if (this.state.started && this.state.t < END[this.state.runScenario]) this.startClock(this.state.t);
    this.onKey = e => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); this.setState(s => ({ cmdOpen:!s.cmdOpen, cmdQuery:'', cmdIdx:0 })); }
      else if (e.key === 'Escape' && this.state.cmdOpen) this.setState({ cmdOpen:false });
    };
    window.addEventListener('keydown', this.onKey);
  }
  componentWillUnmount(){ this.props.demo.saveRun(this.state); clearInterval(this.iv); this.clearAnalysis(); window.removeEventListener('keydown', this.onKey); }
  commands(running){
    const go = v => this.setState({ view:v });
    const all = [
      { label:'Evaluate candidates', group:'Run', run:() => { go('portfolio'); if (!running) this.startRun(this.state.scenario); } },
      { label:'Reset run', group:'Run', run:() => this.resetRun() },
      { label:'Scenario: Success', group:'Scenario', run:() => { if (!running) this.setState({ scenario:'success' }); } },
      { label:'Scenario: Evaluation fails', group:'Scenario', run:() => { if (!running) this.setState({ scenario:'eval' }); } },
      { label:'Scenario: Repair fails', group:'Scenario', run:() => { if (!running) this.setState({ scenario:'repair' }); } },
      { label:'Go to Overview', group:'Navigate', run:() => go('portfolio') },
      { label:'Open PocketScan', group:'Navigate', run:() => { this.props.demo.navigate('/'); } },
      { label:'Upgrade to Pro', group:'PocketScan', run:() => this.props.demo.navigate('/checkout') },
      { label:'Reset demo', group:'Run', run:() => this.resetRun() }
    ];
    const q = (this.state.cmdQuery || '').trim().toLowerCase();
    return q ? all.filter(c => (c.label + ' ' + c.group).toLowerCase().includes(q)) : all;
  }
  runCmd(c){ this.setState({ cmdOpen:false, cmdQuery:'', cmdIdx:0 }); c.run(); }
  speed(){ return Number(this.props.speed ?? 1) || 1; }
  startRun(sc){
    clearInterval(this.iv);
    this.setState(s => ({ started:true, t:0, runScenario:sc, scenario:sc, runN:s.runN+1 }));
    this.startClock(0);
  }
  startClock(elapsed){
    this.t0 = performance.now() - elapsed * 1000 / this.speed();
    this.iv = setInterval(() => {
      const end = END[this.state.runScenario];
      let t = (performance.now() - this.t0) / 1000 * this.speed();
      if (t >= end) { t = end; clearInterval(this.iv); }
      this.setState({ t });
    }, 100);
  }
  resetRun(){ clearInterval(this.iv); this.clearAnalysis(); this.props.demo.resetDemo(); this.setState({ started:false, t:0, runN:0, scenario:'success', runScenario:'success', sel:'fpocket', pro:false, view:'portfolio', checkout:null }); }
  clearAnalysis(){ clearTimeout(this.aT); clearTimeout(this.sT); clearTimeout(this.g1); clearTimeout(this.g2); }
  async readFile(f){
    this.clearAnalysis();
    const base = { phase:'idle', result:null, notice:'', slow:false };
    if (!/\.pdb$/i.test(f.name)) return this.setState({ ...base, file:null, fileError:'Only .pdb files are accepted.' });
    if (f.size === 0) return this.setState({ ...base, file:null, fileError:'This file is empty.' });
    if (f.size > 10*1024*1024) return this.setState({ ...base, file:null, fileError:'This file is larger than 10 MiB.' });
    const text = await f.text();
    if (!/^(ATOM|HETATM)/m.test(text)) return this.setState({ ...base, file:null, fileError:'No ATOM or HETATM records found in this file.' });
    this.setState({ ...base, file:{ name:f.name, size:f.size }, fileError:'' });
  }
  analyze(){
    if (!this.state.file || this.state.phase === 'loading') return;
    this.clearAnalysis();
    const sc = this.state.pScenario;
    const dur = (sc === 'slow' ? 6000 : 1600);
    this.setState({ phase:'loading', slow:false, result:null, notice:'', stage:0 });
    this.g1 = setTimeout(() => this.setState({ stage:1 }), dur*0.3);
    this.g2 = setTimeout(() => this.setState({ stage:2 }), dur*0.65);
    if (sc === 'slow') this.sT = setTimeout(() => this.setState({ slow:true }), 2500);
    this.aT = setTimeout(() => {
      clearTimeout(this.sT);
      if (sc === 'fail') return this.setState({ phase:'error', slow:false, errorMsg:'The analysis service could not process this structure.' });
      this.setState({ phase:'done', slow:false, result:{ filename:this.state.file.name, mode:'fpocket', pockets: sc === 'empty' ? [] : POCKETS } });
    }, dur);
  }

  renderVals(){
    const st = this.state;
    const snap = snapshot(st.t, st.runScenario, st.started);
    const running = snap.run === 'running';
    const dot = (color, on) => on ? React.createElement('span', { style:{ width:6, height:6, borderRadius:3, background:color, animation:'alPulse 1.1s ease-in-out infinite', flex:'none' } }) : null;
    const decidedN = snap.cands.filter(c => c.status === 'Pass' || c.status === 'Invest').length;
    const doneMs = snap.ms.filter(m => m.status === 'Complete').length;
    const sel = snap.cands.find(c => c.id === st.sel) || snap.cands[1];
    const sp = PILL[sel.status];
    const failTitle = st.runScenario === 'eval' ? 'Evaluation failed' : 'Repair failed';
    const failBody = st.runScenario === 'eval'
      ? 'Evidence collection timed out for 2 candidates. No investment was made and nothing was launched.'
      : 'The build did not pass after 3 attempts. Deployment and monetization were not started.';
    const liveLabel = snap.live ? 'Live' : snap.invested && snap.run === 'running' ? 'Building' : snap.run === 'failed' && snap.invested ? 'Failed' : 'Not launched';
    const liveColor = snap.live ? C.ok : liveLabel === 'Building' ? C.brand : liveLabel === 'Failed' ? C.err : C.t3;

    const cmds = this.commands(running);
    const cmdIdx = Math.min(st.cmdIdx || 0, Math.max(0, cmds.length - 1));
    const r = st.result;
    const pockets = r ? r.pockets.map((p, i) => {
      const locked = !st.pro && i > 0;
      const v = p.druggability >= 0.7 ? ['Promising','#34D399','rgba(52,211,153,.12)'] : p.druggability >= 0.5 ? ['Moderate','#FBBF24','rgba(251,191,36,.12)'] : ['Weak','#A1A1A1','rgba(255,255,255,.06)'];
      return { rank:'Pocket ' + (i+1), locked, verdict:v[0], vFg:v[1], vBg:v[2],
        blur: locked ? 'blur(7px)' : 'none', opacity: locked ? .55 : 1,
        drug: p.druggability.toFixed(2), drugPct:(p.druggability*100)+'%',
        volume: p.volume.toFixed(1) + ' Å³', score: p.score.toFixed(2) };
    }) : [];
    const stepAt = st.phase === 'done' ? 3 : st.phase === 'idle' ? 1 : 2;
    const lockedCount = r && !st.pro ? Math.max(0, r.pockets.length - 1) : 0;
    const fileSize = st.file ? (st.file.size < 1024 ? st.file.size + ' B' : (st.file.size/1024).toFixed(1) + ' KB') : '';
    const canAnalyze = !!st.file && st.phase !== 'loading';

    return {
      panelTitle: (st.rail || 'portfolio') === 'portfolio' ? 'Portfolio' : 'Products',
      isRailPortfolio: (st.rail || 'portfolio') === 'portfolio', isRailProducts: st.rail === 'products',
      railPortfolio: () => this.setState({ rail:'portfolio' }), railProducts: () => this.setState({ rail:'products' }),
      railPortBg: (st.rail || 'portfolio') === 'portfolio' ? '#1A1A1A' : 'transparent', railPortColor: (st.rail || 'portfolio') === 'portfolio' ? '#EDEDED' : '#8F8F8F',
      railProdBg: st.rail === 'products' ? '#1A1A1A' : 'transparent', railProdColor: st.rail === 'products' ? '#EDEDED' : '#8F8F8F',
      railNone: 'transparent', railIdle: '#8F8F8F',
      pipePct: (doneMs / 5 * 100) + '%',
      panelCands: snap.cands.map(c => ({ repo:c.repo, status:c.status, dot:PILL[c.status].fg, color: c.id === sel.id ? '#EDEDED' : '#A1A1A1',
        bg: c.id === sel.id ? '#1A1A1A' : 'transparent', onClick: () => this.setState({ sel:c.id }) })),
      tabs: [
        { label:'Overview', onClick:() => this.setState({ view:'portfolio' }), color:C.text, line:'inset 0 -2px 0 #EDEDED', hasDot:false },
        { label:'PocketScan', onClick:() => this.props.demo.navigate('/'), color:C.t2, line:'none', hasDot:true, meta:liveLabel, dotColor:liveColor }
      ],
      cmdOpen: !!st.cmdOpen, cmdQuery: st.cmdQuery || '',
      cmdItems: cmds.map((c, i) => ({ label:c.label, group:c.group, run:() => this.runCmd(c), hover:() => this.setState({ cmdIdx:i }),
        bg: i === cmdIdx ? '#1A1A1A' : 'transparent', color: i === cmdIdx ? '#EDEDED' : '#A1A1A1' })),
      cmdEmpty: cmds.length === 0,
      openCmd: () => this.setState({ cmdOpen:true, cmdQuery:'', cmdIdx:0 }),
      closeCmd: () => this.setState({ cmdOpen:false }),
      stop: e => e.stopPropagation(),
      cmdInput: e => this.setState({ cmdQuery:e.target.value, cmdIdx:0 }),
      cmdKey: e => {
        if (e.key === 'ArrowDown') { e.preventDefault(); this.setState({ cmdIdx: Math.min(cmds.length - 1, cmdIdx + 1) }); }
        else if (e.key === 'ArrowUp') { e.preventDefault(); this.setState({ cmdIdx: Math.max(0, cmdIdx - 1) }); }
        else if (e.key === 'Enter' && cmds[cmdIdx]) { e.preventDefault(); this.runCmd(cmds[cmdIdx]); }
      },
      liveLabel, liveColor,
      crumb: st.view === 'portfolio' ? 'Portfolio' : 'PocketScan',
      runIdLabel: st.started ? 'run_' + String(st.runN).padStart(4,'0') : 'no run',
      isPortfolio: st.view === 'portfolio', isPocket: st.view === 'pocket',

      scenarios: [['success','Success'],['eval','Evaluation fails'],['repair','Repair fails']].map(([id,label]) => ({
        label, onClick: () => { if (!running) this.setState({ scenario:id }); },
        color: st.scenario === id ? C.text : C.t2, bg: st.scenario === id ? C.s2 : 'transparent',
        cursor: running ? 'default' : 'pointer', opacity: running && st.scenario !== id ? .45 : 1 })),
      started: st.started,
      evaluate: () => { if (!running) this.startRun(st.scenario); },
      reset: () => this.resetRun(),
      retry: () => this.startRun('success'),
      runBtnLabel: running ? 'Evaluating…' : st.started ? 'Run again' : 'Evaluate candidates',
      runBtnCursor: running ? 'default' : 'pointer', runBtnOpacity: running ? .55 : 1,
      isFailed: snap.run === 'failed', errorTitle: failTitle, errorBody: failBody,
      isLive: snap.live, openPocket: () => { this.props.demo.navigate('/'); },

      stats: [
        { label:'Capital', value:'$10.00', sub: snap.invested ? 'Allocated to fpocket/fpocket' : 'Unallocated', color:C.text },
        { label:'Active investments', value: snap.invested ? '1' : '0', sub: snap.invested ? 'fpocket/fpocket' : 'None yet', color: C.text },
        { label:'Launched products', value: snap.live ? '1' : '0', sub: snap.live ? 'PocketScan' : 'None yet', color: snap.live ? C.ok : C.text },
        { label:'Elapsed', value: fmt(st.t), sub: snap.run === 'idle' ? 'Idle' : snap.run === 'running' ? 'Running' : snap.run === 'complete' ? 'Complete' : 'Failed',
          color: snap.run === 'failed' ? C.err : C.text }
      ],
      progressPct: (st.started ? Math.min(100, st.t / END.success * 100) : 0) + '%',
      progressColor: snap.run === 'failed' ? C.err : snap.live ? C.ok : C.brand,

      candSummary: st.started ? decidedN + ' of 3 decided' : '3 queued',
      candidates: snap.cands.map(c => { const p = PILL[c.status]; return {
        repo:c.repo, blurb:c.blurb, status:c.status, fg:p.fg, bg:p.bg, dot: dot(p.fg, p.pulse),
        decided: c.decidedAt != null ? fmt(c.decidedAt) : '—',
        rowBg: c.id === sel.id ? '#18181A' : 'transparent',
        rowShadow: c.id === sel.id ? 'inset 2px 0 0 #EDEDED' : 'none',
        onClick: () => this.setState({ sel:c.id }) }; }),
      report: { repo:sel.repo, status:sel.status, fg:sp.fg, bg:sp.bg, dot:dot(sp.fg, sp.pulse),
        hasDecision: sel.status === 'Pass' || sel.status === 'Invest', verdict: sel.status + '.', decision: sel.decision, sections: sel.sections },

      pipelineSummary: doneMs + ' of 5 complete',
      milestones: snap.ms.map((m, i) => {
        const s = m.status;
        const fg = s === 'Complete' ? C.ok : s === 'In progress' ? C.brand : s === 'Failed' ? C.err : C.t3;
        return { label:m.label, detail:m.detail, status:s, fg, dot:dot(fg, s === 'In progress'),
          glyph: s === 'Complete' ? '✓' : s === 'Failed' ? '×' : String(i+1),
          labelColor: s === 'Pending' ? C.t2 : C.text,
          border: s === 'Pending' ? 'rgba(255,255,255,.16)' : fg,
          bg: s === 'Complete' ? 'rgba(52,211,153,.1)' : s === 'Failed' ? 'rgba(255,90,95,.1)' : s === 'In progress' ? 'rgba(255,107,44,.1)' : 'transparent' };
      }),
      events: snap.events.map(e => ({ time:fmt(e[0]), text:e[1],
        color: { info:C.info, muted:C.t3, err:C.err, ok:C.ok, brand:C.brand }[e[2]],
        textColor: e[2] === 'err' ? C.err : e[2] === 'brand' ? C.brand : e[2] === 'muted' ? C.t2 : C.text })),
      noEvents: snap.events.length === 0, eventCount: snap.events.length + ' events',
      integrations: [['Brainbase','Agent orchestration'],['Anthropic','Agent reasoning'],['Cloudflare','Hosting and runtime'],['Stripe','Billing and entitlements']].map(([name,role]) => ({ name, role })),

      pro: st.pro, notPro: !st.pro,
      planLabel: st.pro ? 'Pro' : 'Free', planFg: st.pro ? C.brand : C.t2, planBg: st.pro ? 'rgba(255,107,44,.14)' : 'rgba(255,255,255,.06)',
      resetAccess: () => { store.set(false); this.setState({ pro:false, notice:'Access reset to Free.' }); },
      notice: st.notice,
      dropBorder: st.drag ? C.brand : 'rgba(255,255,255,.16)',
      dropBg: st.drag ? 'rgba(255,107,44,.07)' : '#000',
      dragOver: e => { e.preventDefault(); if (!st.drag) this.setState({ drag:true }); },
      dragLeave: () => this.setState({ drag:false }),
      drop: e => { e.preventDefault(); this.setState({ drag:false }); const f = e.dataTransfer.files[0]; if (f) this.readFile(f); },
      pickFile: e => { const f = e.target.files[0]; e.target.value = ''; if (f) this.readFile(f); },
      useSample: () => { this.clearAnalysis(); this.setState({ file:{ name:'sample-fixture.pdb', size:SAMPLE.length }, fileError:'', phase:'idle', result:null, notice:'' }); },
      fileTitle: st.file ? st.file.name : 'Drop a .pdb file or click to browse',
      fileSub: st.file ? fileSize + ' · ready to scan' : '',
      fileError: st.fileError,
      pScenarios: [['success','Success'],['empty','No pockets'],['fail','Failure'],['slow','Slow']].map(([id,label]) => ({
        label, onClick: () => this.setState({ pScenario:id }),
        color: st.pScenario === id ? '#EDEDED' : '#A1A1A1', bg: st.pScenario === id ? '#262626' : 'transparent', shadow: 'none' })),
      analyze: () => this.analyze(),
      cancel: () => { this.clearAnalysis(); this.setState({ phase:'cancelled', slow:false }); },
      analyzeCursor: canAnalyze ? 'pointer' : 'default', analyzeOpacity: canAnalyze ? 1 : .45,
      isIdle: st.phase === 'idle', isLoading: st.phase === 'loading', isError: st.phase === 'error', isCancelled: st.phase === 'cancelled',
      isEmpty: st.phase === 'done' && r && r.pockets.length === 0, isDone: st.phase === 'done' && r && r.pockets.length > 0,
      slow: st.slow, errorMsg: st.errorMsg, fileName: st.file ? st.file.name : '',
      sweep: React.createElement('div', { style:{ width:'40%', height:4, background:C.brand, borderRadius:2, animation:'alSweep 1.1s ease-in-out infinite' } }),
      resultMeta: r ? r.filename + ' · ' + r.mode : '',
      pockets, hasLocked: lockedCount > 0, lockedCount,
      steps: ['Upload','Analyze','Results'].map((label, i) => { const n = i+1, cur = n === stepAt, done = n < stepAt; return {
        label, num: done ? '✓' : String(n), notLast: i < 2, weight: cur ? 600 : 500,
        color: cur || done ? '#EDEDED' : '#8F8F8F', numFg: cur || done ? '#000' : '#8F8F8F',
        numBg: cur ? '#EDEDED' : done ? '#34D399' : '#1F1F1F' }; }),
      stages: ['Reading structure','Finding cavities','Scoring pockets'].map((label, i) => { const s = st.stage || 0, done = i < s, cur = i === s; return {
        label, glyph: done ? '✓' : '', weight: cur ? 600 : 400, color: done || cur ? '#EDEDED' : '#8F8F8F',
        bg: done ? '#34D399' : 'transparent', border: done ? '#34D399' : cur ? '#FF6B2C' : 'rgba(255,255,255,.2)' }; }),
      foundTitle: r ? 'We found ' + r.pockets.length + ' pockets in ' + r.filename : '',
      hasFile: !!st.file, noFile: !st.file,
      removeFile: () => { this.clearAnalysis(); this.setState({ file:null, fileError:'', phase:'idle', result:null }); },
      startOver: () => { this.clearAnalysis(); this.setState({ file:null, fileError:'', phase:'idle', result:null, slow:false }); },
      backToConsole: () => this.setState({ view:'portfolio' }),

      checkoutOpen: !!st.checkout,
      checkoutTitle: st.checkout === 'success' ? 'Upgrade complete' : st.checkout === 'cancelled' ? 'Checkout' : 'Upgrade to Pro',
      coPlan: st.checkout === 'open', coSuccess: st.checkout === 'success', coCancelled: st.checkout === 'cancelled',
      openCheckout: () => this.setState({ checkout:'open' }),
      closeCheckout: () => this.setState({ checkout:null }),
      simSuccess: () => { store.set(true); this.clearAnalysis(); this.setState({ pro:true, checkout:'success', result:null, phase:'idle', file:null, notice:'' }); },
      simCancel: () => this.setState({ checkout:'cancelled' })
    };
  }
}
